import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"胶的热流与回流","description":"","frontmatter":{"title":"胶的热流与回流","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-reflow.md","filePath":"litho/resist-reflow.md","lastUpdated":1789023840000}'),h={name:"litho/resist-reflow.md"};function _(c,a,B,A,T,f){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="胶的热流与回流" tabindex="-1">胶的热流与回流 <a class="header-anchor" href="#胶的热流与回流" aria-label="Permalink to &quot;胶的热流与回流&quot;">​</a></h1><div class="epigraph"><p>显影已经切出浮雕之后，再加热可以把棱角流圆、把孔收小：这是黏滞流动，不是第二次 PEB 催化。</p><footer>—— 据产线回流（resist reflow）工艺通称；聚合物流动见 Tg 以上的黏度语言</footer></div><p><a href="/litho/dose-focus-coupling">上一课</a>把曝光–显影窗写到平均 CD。缺口是显影后还可以再动一次几何：热回流。接触孔缩小、侧壁修圆、有时故意把线端变钝，都走这条路。本课钉回流。流动能不能发生，取决于玻璃化温度与自由体积，留给<a href="/litho/tg-free-volume">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PEB 发生在显影前，对象是酸与保护基。回流发生在显影后（有时在硬烘），对象是已经成形的聚合物浮雕。温度够高、时间够长，表面张力驱动材料从高曲率处流向低曲率处：孔的顶角变圆、孔径缩小，线的肩变塌。光学剂量没有再写一次，CD 却变了——故障隔离时若仍去拧扫描机，会拧错执行器。</p><p>缺口不是再讲 Arrhenius 催化，而是：这是流体力学尺度的质量守恒，潜像化学已经冻结（除非残留溶剂还在塑化）。把回流写成「又一次 PEB」，会把酸核和黏度混成一个烘箱配方。</p><h3 id="故意回流与事故回流" tabindex="-1">故意回流与事故回流 <a class="header-anchor" href="#故意回流与事故回流" aria-label="Permalink to &quot;故意回流与事故回流&quot;">​</a></h3><p>孔层有时故意回流来买更小的 ADI 孔。线层通常禁止：肩一塌，CD 与侧壁角一起漂，刻蚀转移失控。同一条热板程序，对孔是工艺，对线是缺陷。规格必须按图形类别写。</p><p><span class="marginnote">回流改变的是显影后体积分配，不增加衬度。NILS 不够的孔回流之后可以变圆变小，但随机缺孔不会被「流没」；材料从四周挤入，LCDU 可能更差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>旋钮：温度相对 \\(T_g\\) 的距离、时间、升温斜率、胶厚与图形密度。表征：回流前后 CD、侧壁、孔椭圆度、膜厚。密集图形之间的材料竞争会造成邻近相关的 CD 漂移，看起来像 OPE——要用「只回流、不改曝光」的对照矩阵拆开。</p><p>仿真：连续介质黏流 + 表面张力，输入黏度 \\(\\eta(T)\\)。不需要再解 Dill 方程。OPC 若在回流层上做，必须把回流核标定进紧凑模型，否则平均边会对，孔阵列的密度效应会撒谎。</p>',12)),(e(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADI%5B%22%E6%98%BE%E5%BD%B1%E5%90%8E%E6%B5%AE%E9%9B%95%22%5D%20--%3E%20HEAT%5B%22T%20%3E%20Tg%20%E5%9B%9E%E6%B5%81%22%5D%0A%20%20HEAT%20--%3E%20ROUND%5B%22%E6%9B%B2%E7%8E%87%E9%A9%B1%E5%8A%A8%E6%B5%81%E5%8A%A8%22%5D%0A%20%20ROUND%20--%3E%20HOLE%5B%22%E5%AD%94%E5%BE%84%E7%BC%A9%E5%B0%8F%20%2F%20%E8%82%A9%E5%A1%8C%22%5D%0A%20%20TG%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9ATg%20%E4%B8%8E%E8%87%AA%E7%94%B1%E4%BD%93%E7%A7%AF%22%5D%20--%3E%20HEAT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>聚合物在 \\(T_g\\) 以上进入高弹/黏流区，有效黏度下降若干数量级。表面能最小化让凸肩塌、凹孔收。厚胶、大曲率（小孔、尖线端）流动更快。残留溶剂当增塑剂，把有效 \\(T_g\\) 压低，同一热板设定下流得更狠——下一课与 PAB 课会接这句话。</p><p>酸催化在回流温度也可能继续，若显影后仍有活酸。那是污染项：正胶残留酸会让回流伴随额外体积收缩。工艺上要声明是「纯流动」还是「流动 + 残余反应」。</p><p><span class="marginnote">193 nm CAR 的 \\(T_g\\) 常靠近 PEB 设定，回流窗口窄。i 线 novolac 硬烘回流是更老的工作点，不要把两套温度表复印。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写某供应商的回流食谱。不把回流当 RET：它改的是已印图形的三维，救不了零级偏置。下一课给出 \\(T_g\\) 与自由体积，使「为什么这条胶流、那条不流」有聚合物语言。老化与保质会改残留溶剂与 \\(T_g\\)，再下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回流是显影后的黏滞流动，不是 PEB 催化的别名。</li><li>孔可故意缩小；线肩塌通常是事故。</li><li>邻近密度会进入回流 CD，对照实验要关掉曝光变量。</li><li>残留溶剂降低有效 \\(T_g\\)，同一热板结果不同。</li><li>出处：产线 resist reflow 通称；聚合物 \\(T_g\\) 以上流动；Mack / Levinson 工艺叙述。</li></ul>',8))])}const D=i(h,[["render",_]]);export{u as __pageData,D as default};
